#!/usr/bin/env node
/**
 * Writes src/audio/calibration.ts from the sandbox calibration pass:
 *   node tools/shot.cjs "/sandbox/audio/?calibrate=1" --timeout 2400000 --eval "__calibration" | node sandbox/audio/write-calibration.mjs
 * Do not edit files under src/audio or sandbox/audio while the pass runs: the dev server reloads the page.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const input = fs.readFileSync(0, 'utf8');
const line = input.split('\n').find((l) => l.startsWith('[eval] {') && l.includes('"sfx"'));
if (!line) {
  console.error('no calibration JSON found on stdin');
  process.exit(1);
}
const cal = JSON.parse(line.slice('[eval] '.length));
const table = (o) =>
  Object.keys(o).sort().map((k) => `  ${/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k)}: ${Number(o[k].toPrecision(4))},`).join('\n');
const out = `/**
 * Measured normalisation (GENERATED by the audio sandbox — do not edit by hand):
 *   node tools/shot.cjs "/sandbox/audio/?calibrate=1" --timeout 2400000 --eval "__calibration" | node sandbox/audio/write-calibration.mjs
 * (add &only=sfx|music|stinger|ambience and &ids=a,b to redo a part; everything else is kept as it is.)
 *
 * Every value was measured at the final output, through the whole mix chain, at the reference volume
 * settings, on a chain that had been running for half a second (never on a cold one).
 *  SFX_NORM[id]    scales a recipe so that its LOUDNESS (loudest 100 ms, K-weighted) lands on \`db − 9\`, with
 *                  its true peak held under \`min(−5, db + 8)\` dBFS — see sfx/recipe.ts.
 *  MUSIC_NORM[s]   scales a score state so that its RMS at the reference intensity lands on its \`db\`, and at
 *                  full intensity stays within \`db + 2.5\` RMS and −5.5 dBFS peak (99.99th percentile). \`stinger:*\` as SFX.
 *  AMB_NORM[id]    scales a bed so that its RMS lands on its \`db\`.
 * Missing entries fall back to defaults and the sandbox report flags them NOCAL.
 */
export const SFX_NORM: Readonly<Record<string, number>> = {
${table(cal.sfx)}
};

export const MUSIC_NORM: Readonly<Record<string, number>> = {
${table(cal.music)}
};

export const AMB_NORM: Readonly<Record<string, number>> = {
${table(cal.amb)}
};
`;
const file = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../src/audio/calibration.ts');
fs.writeFileSync(file, out);
console.log(`wrote ${file}: ${Object.keys(cal.sfx).length} sfx, ${Object.keys(cal.music).length} music, ${Object.keys(cal.amb).length} ambience`);
if (cal.log) console.log(cal.log.join('\n'));
